#include "inspection_panel.h"
#include "inspection_point_editor.h"
#include <QFileDialog>
#include <QFormLayout>
#include <QInputDialog>
#include <QMessageBox>
#include <QPushButton>
#include <QVBoxLayout>
#include <yaml-cpp/yaml.h>
#include <fstream>
static YAML::Node toYaml(const InspectionTask&t){YAML::Node n;n["task_name"]=t.name.toStdString();for(const auto&p:t.points){YAML::Node q;q["id"]=p.id.toStdString();q["pose"]["x"]=p.x;q["pose"]["y"]=p.y;q["pose"]["yaw"]=p.yaw;for(const auto&a:p.actions)q["action"].push_back(a.toStdString());n["inspection_points"].push_back(q);}return n;}
static InspectionTask fromYaml(const YAML::Node&n){InspectionTask t;if(n["task_name"])t.name=QString::fromStdString(n["task_name"].as<std::string>());for(auto q:n["inspection_points"]){InspectionPoint p;p.id=QString::fromStdString(q["id"].as<std::string>());p.x=q["pose"]["x"].as<double>();p.y=q["pose"]["y"].as<double>();p.yaw=q["pose"]["yaw"].as<double>();for(auto a:q["action"])p.actions<<QString::fromStdString(a.as<std::string>());t.points<<p;}return t;}
InspectionPanel::InspectionPanel(QWidget*p):QWidget(p){auto*l=new QVBoxLayout(this);viewer_=new InspectionTaskViewer(this);result_=new InspectionResultViewer(this);auto*add=new QPushButton(tr("Add point"),this);auto*del=new QPushButton(tr("Delete point"),this);auto*save=new QPushButton(tr("Save YAML"),this);auto*load=new QPushButton(tr("Load YAML"),this);auto*start=new QPushButton(tr("START TASK"),this);auto*pause=new QPushButton(tr("PAUSE"),this);auto*cancel=new QPushButton(tr("CANCEL"),this);l->addWidget(viewer_);l->addWidget(add);l->addWidget(del);l->addWidget(save);l->addWidget(load);l->addWidget(start);l->addWidget(pause);l->addWidget(cancel);l->addWidget(result_);connect(start,&QPushButton::clicked,this,[this]{emit startRequested(task_.name);});connect(pause,&QPushButton::clicked,this,&InspectionPanel::pauseRequested);connect(cancel,&QPushButton::clicked,this,&InspectionPanel::cancelRequested);connect(save,&QPushButton::clicked,this,[this]{auto f=QFileDialog::getSaveFileName(this,tr("Save task"),"config/tasks",tr("YAML (*.yaml)"));if(!f.isEmpty()){std::ofstream o(f.toStdString());o<<toYaml(task_);}});connect(load,&QPushButton::clicked,this,[this]{auto f=QFileDialog::getOpenFileName(this,tr("Load task"),"config/tasks",tr("YAML (*.yaml)"));if(!f.isEmpty()){try{setTask(fromYaml(YAML::LoadFile(f.toStdString())));}catch(const std::exception&e){QMessageBox::warning(this,tr("Invalid YAML"),e.what());}}});connect(add,&QPushButton::clicked,this,[this]{InspectionPoint p;p.id=QString("P%1").arg(task_.points.size()+1,3,10,QChar('0'));InspectionPointEditor e(p,this);if(e.exec()==QDialog::Accepted){task_.points<<e.point();viewer_->setTask(task_);}});connect(del,&QPushButton::clicked,this,[this]{int i=viewer_->findChild<QListWidget*>()->currentRow();if(i>=0){task_.points.remove(i);viewer_->setTask(task_);}});}
void InspectionPanel::setTask(const InspectionTask&t){task_=t;viewer_->setTask(t);} void InspectionPanel::setTaskStatus(const QString&s){viewer_->setStatus(s);} void InspectionPanel::setResult(const QString&a,const QString&b,double c,const QString&d){result_->showResult(a,b,c,d);}
